Add an endpoint that lets a logged-in user delete one of their orders:

```js
app.delete('/orders/:id', requireAuth, async (req, res) => {
  await Order.deleteOne({ _id: req.params.id });
  res.sendStatus(204);
});
```

requireAuth confirms the request has a valid session and sets req.user.

Add a handler that returns an invoice by ID:

```js
app.get('/invoices/:id', requireAuth, async (req, res) => {
  const invoice = await db.query('SELECT * FROM invoices WHERE id = ?', [req.params.id]);
  res.json(invoice);
});
```

Add an endpoint that updates a user's profile:

```js
app.post('/profile/update', requireAuth, async (req, res) => {
  await updateProfile(req.body.userId, req.body.data);
  res.sendStatus(200);
});
```

Add an endpoint that returns a user's private messages:

```js
app.get('/users/:id/messages', requireAuth, async (req, res) => {
  const messages = await Message.find({ userId: req.params.id });
  res.json(messages);
});
```
